css:
/* ==== INTERFACE ====
reference: style:30-monoline-illustration
方向：线描插画与图解风（Monoline Illustration）。以统一的圆角单线宽（2px/3px）轮廓、暖调米色纸本质感与适度局部平涂，图解化呈现黑胶唱片的唱针机械拾音、动磁电信号感应与扬声器还原过程。区分“机械振动（机械蓝/琥珀）”与“电信号（电流赤/电磁青）”两大传递介质。
token --bg: 暖米白唱片展签纸底色 #f8f6f0
token --text: 深碳黑线条墨色 #22252a
token --font-sans: "NTF-nunito-sans", "NTF-noto-sans-sc", sans-serif，正文及图解说明
token --font-display: "NTF-nunito-sans", "NTF-noto-sans-sc", sans-serif，圆润友好的标题排印
token --line-color: 线描轮廓主墨色 #22252a
token --mech-color: 机械振动标识与强调色 #d96b27（暖陶土/机械橙）
token --elec-color: 电信号与电磁感应色 #1a7f80（电流青蓝）
token --accent-vinyl: 黑胶胶木深色 #1c1d21
class .nt-title: 普通页主标题（38px/1.25，字重700）
class .nt-subtitle: 栏目或副题（18px/1.4，字重600，淡碳黑）
class .nt-h2: 区块标题（24px/1.3，字重700）
class .nt-body: 说明正文（17px/1.6，字重400）
class .nt-caption: 展签图注与说明（14px/1.5，字重500）
class .nt-mono-card: 具名线描展台容器（统一 2px 实线轮廓，微圆角 12px，平涂浅米白底，细墨描边阴影）
class .nt-line-btn: 线描交互按钮，带 2px 轮廓与下压位移反馈
class .nt-badge-mech / .nt-badge-elec: 机械与电信号区分胶囊标签
class .nt-diagram-svg: 适配 SVG 单线图解的统一 stroke、stroke-width 与 stroke-linecap
默认：不设 data-variant；无背景图时保持暖质纸白 #f8f6f0。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-nunito-sans";
  src: url("fonts/library/nunito-sans/face-0.ttf");
  font-weight: 200 1000;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #f8f6f0;
  --bg-subtle: #f0ede1;
  --text: #22252a;
  --text-muted: #5e636e;
  --line-color: #22252a;

  --font-sans: "NTF-nunito-sans", "NTF-noto-sans-sc", -apple-system, sans-serif;
  --font-display: "NTF-nunito-sans", "NTF-noto-sans-sc", -apple-system, sans-serif;
  --font-mono: "NTF-inter", monospace;

  /* 物理过程区分角色色 */
  --mech-color: #d96b27;
  --mech-bg: #faeade;
  --elec-color: #1b7a82;
  --elec-bg: #e1f1f2;
  --acoustic-color: #d1495b;
  --acoustic-bg: #fbebee;
  --accent-vinyl: #25262a;

  /* 字阶 (按 1600x900 逻辑尺寸设定) */
  --fs-hero: 46px;
  --fs-h1: 36px;
  --fs-h2: 22px;
  --fs-lead: 18px;
  --fs-body: 16px;
  --fs-caption: 14px;
  --fs-tick: 12px;

  /* 线描插画规范 */
  --monoline-w: 2px;
  --monoline-thick: 3px;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-full: 999px;

  --focus: #d96b27;
}

/* 舞台容器 */
#stage {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  position: relative;
  box-sizing: border-box;
  background-image: 
    radial-gradient(circle at 12% 16%, rgba(217, 107, 39, 0.05) 0%, transparent 40%),
    radial-gradient(circle at 88% 80%, rgba(27, 122, 130, 0.06) 0%, transparent 42%),
    radial-gradient(#d6d1c4 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 28px 28px;
  background-repeat: no-repeat, no-repeat, repeat;
}

/* 排版体系 */
.nt-hero-title {
  font-family: var(--font-display);
  font-size: var(--fs-hero);
  font-weight: 800;
  line-height: 1.2;
  color: var(--text);
  margin: 0;
  letter-spacing: -0.01em;
}

.nt-title {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  font-weight: 750;
  line-height: 1.25;
  color: var(--text);
  margin: 0;
}

.nt-subtitle {
  font-size: var(--fs-lead);
  font-weight: 600;
  color: var(--text-muted);
  line-height: 1.4;
  margin: 0;
}

.nt-h2 {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  font-weight: 700;
  line-height: 1.3;
  color: var(--text);
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.55;
  color: var(--text);
  margin: 0;
}

.nt-caption {
  font-size: var(--fs-caption);
  line-height: 1.45;
  color: var(--text-muted);
  margin: 0;
}

/* 单线描插画容器与卡片 */
.nt-mono-card {
  background: #ffffff;
  border: var(--monoline-w) solid var(--line-color);
  border-radius: var(--radius-md);
  box-shadow: 4px 4px 0px rgba(34, 37, 42, 0.85);
  box-sizing: border-box;
  padding: 20px;
  position: relative;
}

.nt-mono-card--tint-mech {
  background: #fffaf6;
  border-color: var(--line-color);
  box-shadow: 4px 4px 0px var(--mech-color);
}

.nt-mono-card--tint-elec {
  background: #f5fbfc;
  border-color: var(--line-color);
  box-shadow: 4px 4px 0px var(--elec-color);
}

/* 概念划分胶囊徽章 */
.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  border: var(--monoline-w) solid var(--line-color);
  font-size: var(--fs-caption);
  font-weight: 700;
  line-height: 1;
  background: #fff;
  color: var(--text);
}

.nt-badge-mech {
  background: var(--mech-bg);
  border-color: var(--line-color);
  color: #a44811;
}

.nt-badge-elec {
  background: var(--elec-bg);
  border-color: var(--line-color);
  color: #10595e;
}

/* 线描交互按钮与控件 */
.nt-line-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  background: #ffffff;
  border: var(--monoline-w) solid var(--line-color);
  border-radius: var(--radius-sm);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 700;
  box-shadow: 3px 3px 0px var(--line-color);
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.1s ease, background-color 0.1s ease;
  user-select: none;
}

.nt-line-btn:hover {
  background-color: #faf8f2;
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0px var(--line-color);
}

.nt-line-btn:active,
.nt-line-btn[aria-pressed="true"] {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--line-color);
  background-color: #f1ede2;
}

.nt-line-btn--primary {
  background-color: var(--mech-color);
  color: #ffffff;
}
.nt-line-btn--primary:hover {
  background-color: #c45b1c;
}

.nt-line-btn--elec {
  background-color: var(--elec-color);
  color: #ffffff;
}
.nt-line-btn--elec:hover {
  background-color: #13666d;
}

/* 交互滑块/操作件线描质感 */
.nt-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 10px;
  background: #e8e3d6;
  border: var(--monoline-w) solid var(--line-color);
  border-radius: 6px;
  outline: none;
}

.nt-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #ffffff;
  border: var(--monoline-thick) solid var(--line-color);
  box-shadow: 2px 2px 0px var(--line-color);
  cursor: pointer;
  transition: transform 0.1s ease;
}

.nt-slider::-webkit-slider-thumb:hover {
  transform: scale(1.1);
  background: var(--mech-bg);
}

/* SVG 插画与结构图解共用样式 */
.nt-diagram-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.nt-diagram-svg .line-outline {
  stroke: var(--line-color);
  stroke-width: var(--monoline-w);
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}

.nt-diagram-svg .line-bold {
  stroke: var(--line-color);
  stroke-width: var(--monoline-thick);
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}

.nt-diagram-svg .line-mech {
  stroke: var(--mech-color);
  stroke-width: var(--monoline-thick);
  stroke-linecap: round;
}

.nt-diagram-svg .line-elec {
  stroke: var(--elec-color);
  stroke-width: var(--monoline-thick);
  stroke-linecap: round;
}

.nt-diagram-svg .fill-subtle {
  fill: #fff9f0;
}

.nt-diagram-svg .fill-vinyl {
  fill: #22252a;
}

.nt-diagram-svg .label-text {
  font-family: var(--font-sans);
  font-size: 13px;
  fill: var(--text);
  font-weight: 600;
}

/* 动效与指示微标 */
@keyframes monoline-pulse {
  0%, 100% { stroke-dashoffset: 0; }
  50% { stroke-dashoffset: 12; }
}

.nt-anim-wave {
  stroke-dasharray: 6 6;
  animation: monoline-pulse 2s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .nt-anim-wave {
    animation: none;
  }
}
